inline ::flatbuffers::Offset<mplElements> CreatemplElements(
    ::flatbuffers::FlatBufferBuilder &_fbb,
    double SEMI_MAJOR_AXIS_KM = 0.0,
    double ECCENTRICITY = 0.0,
    double INCLINATION_DEG = 0.0,
    double RAAN_DEG = 0.0,
    double ARG_OF_PERIAPSIS_DEG = 0.0,
    double TRUE_ANOMALY_DEG = std::numeric_limits<double>::quiet_NaN(),
    double MEAN_ANOMALY_DEG = std::numeric_limits<double>::quiet_NaN(),
    double ECCENTRIC_ANOMALY_DEG = std::numeric_limits<double>::quiet_NaN(),
    double MU_KM3_S2 = 0.0,
    double ANGULAR_MOMENTUM_KM2_S = 0.0,
    double MEAN_MOTION_DEG_S = 0.0,
    double PERIOD_S = 0.0,
    double PERIAPSIS_RADIUS_KM = 0.0,
    double APOAPSIS_RADIUS_KM = 0.0,
    double ASCENDING_NODE_TRUE_ANOMALY_DEG = std::numeric_limits<double>::quiet_NaN(),
    double MEAN_ARGUMENT_OF_LATITUDE_DEG = std::numeric_limits<double>::quiet_NaN()) {
  mplElementsBuilder builder_(_fbb);
  builder_.add_MEAN_ARGUMENT_OF_LATITUDE_DEG(MEAN_ARGUMENT_OF_LATITUDE_DEG);
  builder_.add_ASCENDING_NODE_TRUE_ANOMALY_DEG(ASCENDING_NODE_TRUE_ANOMALY_DEG);
  builder_.add_APOAPSIS_RADIUS_KM(APOAPSIS_RADIUS_KM);
  builder_.add_PERIAPSIS_RADIUS_KM(PERIAPSIS_RADIUS_KM);
  builder_.add_PERIOD_S(PERIOD_S);
  builder_.add_MEAN_MOTION_DEG_S(MEAN_MOTION_DEG_S);
  builder_.add_ANGULAR_MOMENTUM_KM2_S(ANGULAR_MOMENTUM_KM2_S);
  builder_.add_MU_KM3_S2(MU_KM3_S2);
  builder_.add_ECCENTRIC_ANOMALY_DEG(ECCENTRIC_ANOMALY_DEG);
  builder_.add_MEAN_ANOMALY_DEG(MEAN_ANOMALY_DEG);
  builder_.add_TRUE_ANOMALY_DEG(TRUE_ANOMALY_DEG);
  builder_.add_ARG_OF_PERIAPSIS_DEG(ARG_OF_PERIAPSIS_DEG);
  builder_.add_RAAN_DEG(RAAN_DEG);
  builder_.add_INCLINATION_DEG(INCLINATION_DEG);
  builder_.add_ECCENTRICITY(ECCENTRICITY);
  builder_.add_SEMI_MAJOR_AXIS_KM(SEMI_MAJOR_AXIS_KM);
  return builder_.Finish();
}

