  template <bool B = false>
  bool Verify(::flatbuffers::VerifierTemplate<B> &verifier) const {
    return VerifyTableStart(verifier) &&
           VerifyField<double>(verifier, VT_INITIAL_RADIUS_KM, 8) &&
           VerifyField<double>(verifier, VT_FINAL_RADIUS_KM, 8) &&
           VerifyField<double>(verifier, VT_INTERMEDIATE_RADIUS_KM, 8) &&
           VerifyField<double>(verifier, VT_SPEED_KM_S, 8) &&
           VerifyField<double>(verifier, VT_INCLINATION_CHANGE_DEG, 8) &&
           verifier.EndTable();
  }
  mplTransferRequestT *UnPack(const ::flatbuffers::resolver_function_t *_resolver = nullptr) const;
