  /// read only when HAS_ELAPSED.
  double ELAPSED_S() const {
    return GetField<double>(VT_ELAPSED_S, 0.0);
  }
  /// True when ELAPSED_S is stated (0 is then a real zero-length coast);
  /// false = no coast.
  bool HAS_ELAPSED() const {
    return GetField<uint8_t>(VT_HAS_ELAPSED, 0) != 0;
  }
  /// OrbitGeometry: a burn to apply at the evaluated point;
  /// DeltaVTransform: the delta-v to rotate (its AXES is the source axes).
  const mplBurn *BURN() const {
    return GetPointer<const mplBurn *>(VT_BURN);
  }
  /// DeltaVTransform: axes to rotate the delta-v into.
  mplAxes TO_AXES() const {
    return static_cast<mplAxes>(GetField<uint8_t>(VT_TO_AXES, 0));
  }
  /// AnomalyConversion: eccentricity.
  double ECCENTRICITY() const {
    return GetField<double>(VT_ECCENTRICITY, 0.0);
  }
  /// AnomalyConversion: the anomaly to convert, deg.
  double ANOMALY_DEG() const {
    return GetField<double>(VT_ANOMALY_DEG, 0.0);
  }
  mplAnomalyKind ANOMALY_KIND() const {
    return static_cast<mplAnomalyKind>(GetField<uint8_t>(VT_ANOMALY_KIND, 0));
  }
  /// TimeOfFlight and OrbitSampling: start true anomaly, deg.
  double FROM_TRUE_ANOMALY_DEG() const {
    return GetField<double>(VT_FROM_TRUE_ANOMALY_DEG, 0.0);
  }
  /// TimeOfFlight: end true anomaly, deg.
  double TO_TRUE_ANOMALY_DEG() const {
    return GetField<double>(VT_TO_TRUE_ANOMALY_DEG, 0.0);
  }
  /// TimeOfFlight: whole revolutions to add.
  uint32_t REVOLUTIONS() const {
    return GetField<uint32_t>(VT_REVOLUTIONS, 0);
  }
  /// OrbitSampling: signed sweep from FROM_TRUE_ANOMALY_DEG, deg, at most one
  /// revolution; read only when HAS_SWEEP.
  double SWEEP_DEG() const {
    return GetField<double>(VT_SWEEP_DEG, 0.0);
  }
  /// True when SWEEP_DEG is stated; false = one full revolution forward.
  bool HAS_SWEEP() const {
    return GetField<uint8_t>(VT_HAS_SWEEP, 0) != 0;
  }
  /// OrbitSampling: samples, endpoints included.
  uint32_t SAMPLE_COUNT() const {
    return GetField<uint32_t>(VT_SAMPLE_COUNT, 0);
  }
  template <bool B = false>
  bool Verify(::flatbuffers::VerifierTemplate<B> &verifier) const {
    return VerifyTableStart(verifier) &&
           VerifyOffset(verifier, VT_ORBIT) &&
           verifier.VerifyTable(ORBIT()) &&
           VerifyField<double>(verifier, VT_AT_TRUE_ANOMALY_DEG, 8) &&
           VerifyField<double>(verifier, VT_ELAPSED_S, 8) &&
           VerifyField<uint8_t>(verifier, VT_HAS_ELAPSED, 1) &&
           VerifyOffset(verifier, VT_BURN) &&
           verifier.VerifyTable(BURN()) &&
           VerifyField<uint8_t>(verifier, VT_TO_AXES, 1) &&
           VerifyField<double>(verifier, VT_ECCENTRICITY, 8) &&
           VerifyField<double>(verifier, VT_ANOMALY_DEG, 8) &&
           VerifyField<uint8_t>(verifier, VT_ANOMALY_KIND, 1) &&
           VerifyField<double>(verifier, VT_FROM_TRUE_ANOMALY_DEG, 8) &&
           VerifyField<double>(verifier, VT_TO_TRUE_ANOMALY_DEG, 8) &&
           VerifyField<uint32_t>(verifier, VT_REVOLUTIONS, 4) &&
           VerifyField<double>(verifier, VT_SWEEP_DEG, 8) &&
           VerifyField<uint8_t>(verifier, VT_HAS_SWEEP, 1) &&
           VerifyField<uint32_t>(verifier, VT_SAMPLE_COUNT, 4) &&
           verifier.EndTable();
  }
  mplGeometryRequestT *UnPack(const ::flatbuffers::resolver_function_t *_resolver = nullptr) const;
  void UnPackTo(mplGeometryRequestT *_o, const ::flatbuffers::resolver_function_t *_resolver = nullptr) const;
  static ::flatbuffers::Offset<mplGeometryRequest> Pack(::flatbuffers::FlatBufferBuilder &_fbb, const mplGeometryRequestT* _o, const ::flatbuffers::rehasher_function_t *_rehasher = nullptr);
