inline ::flatbuffers::Offset<mplPhasingSolution> CreatemplPhasingSolution(
    ::flatbuffers::FlatBufferBuilder &_fbb,
    double PHASE_ANGLE_DEG = 0.0,
    double ACHIEVED_PHASE_ANGLE_DEG = 0.0,
    double REQUESTED_SEMI_MAJOR_AXIS_KM = 0.0,
    double REQUESTED_PERIOD_S = 0.0,
    double FLOOR_RADIUS_KM = 0.0,
    bool CLAMPED_TO_FLOOR = false,
    double FAR_APSE_RADIUS_KM = 0.0,
    double PHASING_RADIUS_KM = 0.0,
    double RELATIVE_PHASE_ANGLE_DEG = 0.0,
    double CATCH_UP_ANGLE_DEG = 0.0,
    double FALL_BEHIND_ANGLE_DEG = 0.0,
    mplPhasingDirection DIRECTION = mplPhasingDirection::Shortest,
    ::flatbuffers::Offset<mplElements> CHASER = 0,
    ::flatbuffers::Offset<mplElements> TARGET = 0,
    double RAAN_DIFFERENCE_DEG = 0.0,
    double INCLINATION_DIFFERENCE_DEG = 0.0,
    double PLANE_ANGLE_DEG = 0.0,
    double SEMI_MAJOR_AXIS_DIFFERENCE_KM = 0.0,
    bool COPLANAR = false,
    double COPLANAR_TOLERANCE_DEG = 0.0,
    bool NEAR_CIRCULAR = false,
    double ECCENTRICITY_TOLERANCE = 0.0,
    bool CO_ORBITAL = false,
    double CO_ORBITAL_TOLERANCE_KM = 0.0,
    double CO_ORBITAL_TOLERANCE_FRACTION = 0.0,
    uint32_t RECOMMENDED_REVOLUTIONS = 0,
    bool REVOLUTIONS_FROM_CALLER = false,
    uint32_t MAX_REVOLUTIONS = 0,
    double DELTA_V_BUDGET_KM_S = 0.0,
    bool WITHIN_BUDGET = false) {
  mplPhasingSolutionBuilder builder_(_fbb);
  builder_.add_DELTA_V_BUDGET_KM_S(DELTA_V_BUDGET_KM_S);
  builder_.add_CO_ORBITAL_TOLERANCE_FRACTION(CO_ORBITAL_TOLERANCE_FRACTION);
  builder_.add_CO_ORBITAL_TOLERANCE_KM(CO_ORBITAL_TOLERANCE_KM);
  builder_.add_ECCENTRICITY_TOLERANCE(ECCENTRICITY_TOLERANCE);
  builder_.add_COPLANAR_TOLERANCE_DEG(COPLANAR_TOLERANCE_DEG);
  builder_.add_SEMI_MAJOR_AXIS_DIFFERENCE_KM(SEMI_MAJOR_AXIS_DIFFERENCE_KM);
  builder_.add_PLANE_ANGLE_DEG(PLANE_ANGLE_DEG);
  builder_.add_INCLINATION_DIFFERENCE_DEG(INCLINATION_DIFFERENCE_DEG);
  builder_.add_RAAN_DIFFERENCE_DEG(RAAN_DIFFERENCE_DEG);
  builder_.add_FALL_BEHIND_ANGLE_DEG(FALL_BEHIND_ANGLE_DEG);
  builder_.add_CATCH_UP_ANGLE_DEG(CATCH_UP_ANGLE_DEG);
  builder_.add_RELATIVE_PHASE_ANGLE_DEG(RELATIVE_PHASE_ANGLE_DEG);
  builder_.add_PHASING_RADIUS_KM(PHASING_RADIUS_KM);
  builder_.add_FAR_APSE_RADIUS_KM(FAR_APSE_RADIUS_KM);
  builder_.add_FLOOR_RADIUS_KM(FLOOR_RADIUS_KM);
  builder_.add_REQUESTED_PERIOD_S(REQUESTED_PERIOD_S);
  builder_.add_REQUESTED_SEMI_MAJOR_AXIS_KM(REQUESTED_SEMI_MAJOR_AXIS_KM);
  builder_.add_ACHIEVED_PHASE_ANGLE_DEG(ACHIEVED_PHASE_ANGLE_DEG);
  builder_.add_PHASE_ANGLE_DEG(PHASE_ANGLE_DEG);
  builder_.add_MAX_REVOLUTIONS(MAX_REVOLUTIONS);
  builder_.add_RECOMMENDED_REVOLUTIONS(RECOMMENDED_REVOLUTIONS);
  builder_.add_TARGET(TARGET);
  builder_.add_CHASER(CHASER);
  builder_.add_WITHIN_BUDGET(WITHIN_BUDGET);
  builder_.add_REVOLUTIONS_FROM_CALLER(REVOLUTIONS_FROM_CALLER);
  builder_.add_CO_ORBITAL(CO_ORBITAL);
  builder_.add_NEAR_CIRCULAR(NEAR_CIRCULAR);
  builder_.add_COPLANAR(COPLANAR);
  builder_.add_DIRECTION(DIRECTION);
  builder_.add_CLAMPED_TO_FLOOR(CLAMPED_TO_FLOOR);
  return builder_.Finish();
}

