  auto _MEAN_MOTION_DEG_S = _o->MEAN_MOTION_DEG_S;
  auto _PERIOD_S = _o->PERIOD_S;
  auto _PERIAPSIS_RADIUS_KM = _o->PERIAPSIS_RADIUS_KM;
  auto _APOAPSIS_RADIUS_KM = _o->APOAPSIS_RADIUS_KM;
  auto _ASCENDING_NODE_TRUE_ANOMALY_DEG = _o->ASCENDING_NODE_TRUE_ANOMALY_DEG;
  auto _MEAN_ARGUMENT_OF_LATITUDE_DEG = _o->MEAN_ARGUMENT_OF_LATITUDE_DEG;
