inline const MPL *GetMPL(const void *buf) {
  return ::flatbuffers::GetRoot<MPL>(buf);
}

inline const MPL *GetSizePrefixedMPL(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<MPL>(buf);
}

inline const char *MPLIdentifier() {
  return "$MPL";
}

inline bool MPLBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, MPLIdentifier());
}

inline bool SizePrefixedMPLBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, MPLIdentifier(), true);
}

template <bool B = false>
inline bool VerifyMPLBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<MPL>(MPLIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedMPLBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<MPL>(MPLIdentifier());
}

inline void FinishMPLBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<MPL> root) {
  fbb.Finish(root, MPLIdentifier());
}

inline void FinishSizePrefixedMPLBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<MPL> root) {
  fbb.FinishSizePrefixed(root, MPLIdentifier());
}

inline std::unique_ptr<MPLT> UnPackMPL(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<MPLT>(GetMPL(buf)->UnPack(res));
}

inline std::unique_ptr<MPLT> UnPackSizePrefixedMPL(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<MPLT>(GetSizePrefixedMPL(buf)->UnPack(res));
}

